            appName: { type: "string", maxLength: 40, description: "Shown in the sidebar, page title and login screen" }, defaultTheme: { type: "string", enum: ["dark", "light", "system"], description: "For users who have not picked one" },
            localLoginDisabled: { type: "boolean" }, gravatar: { type: "boolean", description: "Allow Gravatar avatars (browsers then contact gravatar.com). MAILBEACON_GRAVATAR=0 forces off." },
