            matchType: { type: "string", enum: ["recipient", "sender", "subject", "catchall"] }, pattern: { type: "string" },
            order: { type: "integer" }, enabled: { type: "boolean" },
            targetType: { type: "string", enum: ["gotify", "ntfy", "pushover", "apprise", "discord", "slack", "telegram", "webhook", "none"], description: "none = only the saved destinations in options.destinationIds" },
            options: { $ref: "#/components/schemas/RouteOptions" }, ownerId: { type: "integer", description: "Admins only" },
