            trace: { type: "array", items: { type: "object", properties: { id: { type: "integer" }, name: { type: "string" }, matchType: { type: "string" }, enabled: { type: "boolean" }, matches: { type: ["boolean", "null"] }, note: { type: "string" } } } },
