        SelfTest: { type: "object", properties: { at: { type: "string" }, ok: { type: "boolean" }, dryRun: { type: "boolean" }, checks: { type: "array", items: { type: "object", properties: { name: { type: "string" }, ok: { type: "boolean" }, detail: { type: "string" } } } } } },
        Log: { type: "object", properties: { at: { type: "string" }, level: { type: "string" }, msg: { type: "string" } } },
